let lang='fr',mode='swangle',index=0,phase=0,timer=null,loops=null,thermal=null;const $=id=>document.getElementById(id),tr=(fr,en)=>lang==='fr'?fr:en;const blue='#31579c',orange='#b1774b',green='#237e78';
function control(id,fr,en,min,max,value,step,unit){return `<label>${tr(fr,en)}<input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}"><output id="${id}Value">${value} ${unit}</output></label>`}
const value=(id,def)=>$(id)?Number($(id).value):def;
function label(x,y,s,anchor='middle'){return `<text x="${x}" y="${y}" text-anchor="${anchor}">${s}</text>`}
function graph(series,xlim,ylim,xlabel,ylabel,marks=[]){const X=x=>75+(x-xlim[0])/(xlim[1]-xlim[0])*640,Y=y=>310-(y-ylim[0])/(ylim[1]-ylim[0])*270;let s='<svg viewBox="0 0 780 370" role="img" aria-label="'+xlabel+'; '+ylabel+'">';for(let i=0;i<=4;i++){const x=xlim[0]+i/4*(xlim[1]-xlim[0]),y=ylim[0]+i/4*(ylim[1]-ylim[0]);s+=`<path d="M${X(x)} 40V310M75 ${Y(y)}H715" fill="none" stroke="#e2e8ed"/>`+label(X(x),336,Number(x.toPrecision(3)))+label(65,Y(y)+5,Number(y.toPrecision(3)),'end')}
s+=`<path d="M75 ${Y(0)}H715M${X(0)} 40V310" stroke="#8199a7" fill="none"/>`+label(75,23,ylabel,'start')+label(715,363,xlabel,'end');for(const c of series)s+=`<path d="${c.data.map((p,i)=>(i?'L':'M')+X(p.x).toFixed(2)+' '+Y(p.y).toFixed(2)).join(' ')}" fill="none" stroke="${c.color}" stroke-width="2.6" ${c.dash?'stroke-dasharray="7 5"':''}/>`;for(const p of marks)s+=`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="5" fill="${p.color||orange}"/>`+label(X(p.x)+(p.dx||0),Y(p.y)+(p.dy||-14),p.text||'');return s+'</svg>'}
function key(entries){$('legend').innerHTML=entries.map(([name,c])=>`<span style="--color:${c}">${name}</span>`).join('')}
function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent=tr('Lire','Play')}
function play(){if(timer){stop();return}if(index>=240)index=0;phase+=.15;draw();$('play').textContent='Pause';let ticks=0;timer=setInterval(()=>{phase+=.15;ticks++;if(!$('hold').checked&&ticks%3===0)index=Math.min(240,index+1);draw();if(index===240&&!$('hold').checked)stop()},75)}
function render(){stop();index=0;phase=0;document.documentElement.lang=lang;$('transport').hidden=mode!=='zfc';$('particles').innerHTML='';$('particleHint').textContent='';$('play').textContent=tr('Lire','Play');$('reset').textContent=tr('Recommencer','Restart');$('timeline').setAttribute('aria-label',tr('Température du protocole','Protocol temperature'));$('holdLabel').textContent=tr('Maintenir la température','Hold temperature');$('hold').checked=false;$('limitsTitle').textContent='';
if(mode==='swangle'){$('title').textContent=tr('Stoner–Wohlfarth : effet de l’angle','Stoner–Wohlfarth: the role of angle');$('lead').textContent=tr('Le champ fait un angle α avec l’axe facile. φ désigne l’angle entre le moment et le champ. Le curseur modifie la forme du cycle.','The field makes an angle α with the easy axis. φ is the angle between the moment and the field. The slider changes the loop shape.');$('controls').innerHTML=control('angle','Angle champ / axe facile α','Field / easy-axis angle α',0,90,0,1,'°');$('explain').textContent=tr('À 0°, le cycle est rectangulaire. À 90°, la rotation est réversible dans ce modèle idéal.','At 0°, the loop is rectangular. At 90°, rotation is reversible in this ideal model.');$('limits').textContent='';}
if(mode==='mh'){$('title').textContent=tr('Lire un cycle M(H)','Reading an M(H) loop');$('lead').textContent=tr('Le cycle ouvert conserve une rémanence. La réponse superparamagnétique à l’équilibre est réversible.','The open loop retains remanence. The equilibrium superparamagnetic response is reversible.');$('controls').innerHTML='<p>'+tr('Axes faciles aléatoires en 3D','Random 3D easy axes')+'</p>';$('explain').textContent=tr('MS est l’aimantation à saturation. MR est l’aimantation qui reste après retrait du champ saturant. HC est le champ inverse nécessaire pour annuler M. Le rapport MR/MS vaut 0,5 pour un ensemble SW uniaxial sans interactions et à axes aléatoires en 3D.','MS is saturation magnetization. MR is the magnetization remaining after removal of a saturating field. HC is the reverse field needed to bring M to zero. MR/MS equals 0.5 for noninteracting uniaxial SW particles with random 3D easy axes.');$('limits').textContent='';}
if(mode==='initial'){$('title').textContent=tr('Première aimantation : régime de Langevin','Initial magnetization: the Langevin regime');$('lead').textContent=tr('Le champ croît depuis zéro. L’aimantation augmente puis approche asymptotiquement la saturation.','The field increases from zero. Magnetization rises and approaches saturation asymptotically.');$('controls').innerHTML=control('diameter','Diamètre médian','Median diameter',6,22,14,1,'nm')+control('width','Dispersion des tailles σln(d)','Size dispersion σln(d)',0,.3,.12,.02,'')+control('temp','Température','Temperature',100,350,300,10,'K');$('explain').textContent=tr('Le moment de chaque particule vaut μ = MS,cœur V. Une particule plus grande possède un moment plus élevé. Sa réponse se rapproche de la saturation à plus faible champ. La courbe moyenne tient compte de la distribution des volumes.','Each particle has moment μ = MS,core V. A larger particle has a larger moment. Its response approaches saturation at a lower field. The mean curve accounts for the volume distribution.');$('limits').textContent='';}
if(mode==='zfc'){$('title').textContent=tr('Superparamagnétisme et blocage — ZFC / FC','Superparamagnetism and blocking — ZFC / FC');$('lead').textContent=tr('Le moment collectif fluctue sous l’effet de l’agitation thermique. L’ordre ferrimagnétique interne subsiste. τN est le temps de relaxation du moment ; tm est le temps d’observation. Si τN ≪ tm, la particule est superparamagnétique à l’échelle de la mesure. Si τN ≫ tm, elle paraît bloquée. Les courbes ZFC/FC montrent les conséquences de ce blocage.','Thermal agitation makes the collective moment fluctuate. Internal ferrimagnetic order persists. τN is the moment relaxation time; tm is the observation time. If τN ≪ tm, the particle is superparamagnetic on the measurement timescale. If τN ≫ tm, it appears blocked. ZFC/FC curves show the consequences of blocking.');$('controls').innerHTML=`<label>${tr('Protocole','Protocol')}<select id="protocol"><option value="z">ZFC · ${tr('réchauffement','warming')}</option><option value="f">FC · ${tr('refroidissement','cooling')}</option></select></label>`+control('diameter','Diamètre médian','Median diameter',10,16,14,1,'nm')+control('anis','Anisotropie K','Anisotropy K',5,25,20,1,'kJ/m³')+control('tm','Temps d’observation tm','Observation time tm',1,100,100,1,'s');$('explain').textContent=tr('ZFC : refroidissement sans champ, application d’un faible champ, puis réchauffement. Les moments initialement bloqués gardent des orientations désordonnées. Leur déblocage permet une réponse moyenne au champ. À plus haute température, l’agitation thermique réduit cette réponse. FC : refroidissement sous champ ; les grandes particules se bloquent d’abord et conservent une orientation statistiquement favorisée par le champ.','ZFC: zero-field cooling, application of a weak field, then warming. Initially blocked moments retain disordered orientations. Unblocking allows an average response to the field. At higher temperatures, thermal agitation reduces this response. FC: cooling in field; larger particles block first and retain a statistically field-biased orientation.');$('limits').textContent='';}
if(mode==='swangle')$('explain').innerHTML+='<ol><li>'+tr('Particules monodomaines avec rotation cohérente','Single-domain particles with coherent rotation')+'</li><li>'+tr('Anisotropie uniaxiale','Uniaxial anisotropy')+'</li><li>'+tr('Sans interactions ; température nulle','No interactions; zero temperature')+'</li></ol>';const definitions={swangle:["MS est l’aimantation à saturation. MR est la rémanence après retrait d’un champ saturant. HC est le champ inverse qui annule M sur le cycle. HK = 2K/(μ₀MS) est le champ d’anisotropie.","MS is saturation magnetization. MR is remanence after removing a saturating field. HC is the reverse field at which M crosses zero on the loop. HK = 2K/(μ₀MS) is the anisotropy field."],zfc:["TB est défini ici par τN(TB) = tm. Une distribution de tailles produit une distribution de températures de blocage. Le maximum ZFC n’est donc pas une température de blocage unique. Ici, μ₀H = 0,1 mT. Le calcul emploie une approximation à barrière critique : chaque taille bascule à son TB. Dans une mesure réelle, ce passage est progressif et dépend aussi du balayage en température.","TB is defined here by τN(TB) = tm. A size distribution produces a distribution of blocking temperatures. The ZFC maximum is therefore not a single blocking temperature. Here, μ₀H = 0.1 mT. The calculation uses a critical-barrier approximation: each size switches at its TB. In a real measurement, this transition is gradual and also depends on the temperature sweep."],initial:["Langevin décrit ici des moments indépendants à l’équilibre, avec une anisotropie négligée. ξ = μμ₀H/(kBT) compare l’énergie du champ à l’agitation thermique. μ est le moment d’une particule. kB est la constante de Boltzmann. M/MS est une aimantation normalisée. Un système bloqué relève d’une autre description.","Langevin describes independent equilibrium moments here, with anisotropy neglected. ξ = μμ₀H/(kBT) compares field energy with thermal agitation. μ is one particle’s moment. kB is the Boltzmann constant. M/MS is normalized magnetization. A blocked system requires a different description."]};if(definitions[mode])$('explain').innerHTML+='<p>'+definitions[mode][lang==='fr'?0:1]+'</p>';$('equations').innerHTML=FORMULAS[mode];const referenceSets={swangle:[['E. C. Stoner, E. P. Wohlfarth, Phil. Trans. R. Soc. A 1948, 240, 599–642','https://doi.org/10.1098/rsta.1948.0007']],mh:[['E. C. Stoner, E. P. Wohlfarth, Phil. Trans. R. Soc. A 1948, 240, 599–642','https://doi.org/10.1098/rsta.1948.0007'],['C. P. Bean, J. Appl. Phys. 1955, 26, 1381–1383','https://doi.org/10.1063/1.1721912']],zfc:[['L. Néel, Ann. Géophys. 1949, 5, 99–136','https://hal.science/hal-03070532'],['C. P. Bean, J. Appl. Phys. 1955, 26, 1381–1383','https://doi.org/10.1063/1.1721912']],initial:[['K. M. Krishnan, IEEE Trans. Magn. 2010, 46, 2523–2558','https://doi.org/10.1109/TMAG.2010.2046907'],['C. P. Bean, J. Appl. Phys. 1955, 26, 1381–1383','https://doi.org/10.1063/1.1721912']]};referenceSets.zfc.push(['F. Tournus, A. Tamion, J. Magn. Magn. Mater. 2011, 323, 1118–1127','https://doi.org/10.1016/j.jmmm.2010.11.057'],['K. L. Livesey et al., Sci. Rep. 2018, 8, 11166','https://doi.org/10.1038/s41598-018-29501-8']);referenceSets.initial.unshift(["P. Langevin, J. Phys. Theor. Appl. 1905, 4, 678-693", "https://doi.org/10.1051/jphystap:019050040067800"]);for(const k of ['initial','zfc','mh'])referenceSets[k].push(["C. P. Bean, J. D. Livingston, Journal of Applied Physics 1959, 30, S120-S129", "https://doi.org/10.1063/1.2185850"]);$('limits').hidden=true;$('limitsTitle').hidden=true;$('sources').innerHTML='<p class="data-notes">kB = 1.380649 × 10<sup>−23</sup> J/K · <a href="https://physics.nist.gov/cuu/pdf/all.pdf" target="_blank" rel="noopener">NIST CODATA 2022</a></p><h3>'+tr('Publications de référence','Reference publications')+'</h3>'+referenceSets[mode].map(([label,url])=>`<p><a href="${url}" target="_blank" rel="noopener">${label}</a></p>`).join('');
$('controls').querySelectorAll('input,select').forEach(el=>el.oninput=()=>{if($(el.id+'Value'))$(el.id+'Value').textContent=el.value+' '+({angle:'°',diameter:'nm',temp:'K',anis:'kJ/m³',tm:'s'}[el.id]||'');stop();index=0;phase=0;compute()});$('play').onclick=play;$('reset').onclick=()=>{stop();index=0;phase=0;draw()};$('timeline').oninput=()=>{index=+$('timeline').value;draw()};compute();}
function compute(){if(mode==='swangle')loops=swLoop(value('angle',0));if(mode==='mh'){if(!randomCache)randomCache=randomLoop();loops=randomCache}if(mode==='zfc')thermal=zfcCurves(value('diameter',14),value('anis',20)*1000,value('tm',100));draw()}
let randomCache=null;
function orientation(deg){const a=deg*Math.PI/180,cx=230,cy=92;let s='<svg viewBox="0 0 780 190" role="img" aria-label="'+tr('Angle entre champ et axe facile','Angle between field and easy axis')+'"><circle cx="230" cy="92" r="46" fill="#e8eff4" stroke="#9cadba"/>';s+=`<path d="M${cx-68*Math.cos(a)} ${cy+68*Math.sin(a)}L${cx+68*Math.cos(a)} ${cy-68*Math.sin(a)}" stroke="${blue}" stroke-width="3"/>`+`<path d="M100 155H355l-12-7m12 7l-12 7" stroke="${orange}" fill="none" stroke-width="2"/>`+label(390,160,'H','start')+label(510,67,tr('Axe facile','Easy axis'))+label(510,105,'α = '+deg+'°')+label(510,143,tr('Angle entre le champ et l’axe facile','Angle between field and easy axis'));return s+'</svg>'}
function particles(T){const d=value('diameter',14),K=value('anis',20)*1000,tm=value('tm',100),fc=$('protocol').value==='f';let s='<svg viewBox="0 0 780 345" role="img" aria-label="'+tr('Tailles et moments bloqués ou fluctuants','Sizes and blocked or fluctuating moments')+'"><defs><marker id="momentArrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0L5 2.5L0 5" fill="currentColor"/></marker></defs>';s+=`<path d="M280 25H500l-12-6m12 6l-12 6" stroke="${blue}" fill="none" stroke-width="2"/>`+label(520,31,'H','start');
for(let group=0;group<3;group++){const size=d*[.8,1,1.25][group],tb=blockingTemperature(size,K,tm),mobile=T>tb,col=mobile?green:orange,r=16+group*6;for(let j=0;j<6;j++){const i=group*6+j,x=100+j*115,y=95+group*88,easy=(i*2.399)%Math.PI;let a=easy+(i%2?Math.PI:0);if(fc&&!mobile){const bias=L(CORE_MS*volume(size)*.0001/(BOLTZ*tb));const seed=(Math.sin(i*59.8)*3729)%1;a=easy+(Math.abs(seed)<.5+.5*bias*Math.cos(easy)?0:Math.PI)}if(mobile){const bias=Math.min(.4,CORE_MS*volume(size)*.0001/(BOLTZ*T)*.12)*Math.cos(easy),flip=(1+Math.tanh(4*(Math.sin(phase*(1.2+.4*(T/tb))+i*2.71)-bias)))/2;a=easy+Math.PI*flip+.12*Math.sin(phase*3+i)}const dx=Math.cos(a)*r*.8,dy=-Math.sin(a)*r*.8;s+=`<g data-mobile="${mobile}" data-diameter="${size}" data-angle="${a}"><circle cx="${x}" cy="${y}" r="${r}" fill="#edf2f6" stroke="${col}" stroke-width="2.5"/><line x1="${x-.6*dx}" y1="${y-.6*dy}" x2="${x+dx}" y2="${y+dy}" stroke="${col}" style="color:${col}" stroke-width="2.5" marker-end="url(#momentArrow)"/></g>`}s+=label(390,145+group*88,`${size.toFixed(1)} nm · TB ≈ ${tb.toFixed(0)} K · `+(mobile?tr('fluctuant','fluctuating'):tr('bloqué','blocked')))}return s+'</svg>'}
function draw(){if(mode==='swangle'){const a=value('angle',0),r=remanenceAndCoercivity(loops);key([[tr('Branche descendante','Descending branch'),blue],[tr('Branche montante','Ascending branch'),orange]]);$('graph').innerHTML=graph([{data:loops.down,color:blue},{data:loops.up,color:orange}],[-3,3],[-1.1,1.1],'H / HK','M / MS');$('particles').innerHTML=orientation(a);$('readout').textContent=`α = ${a}° · MR/MS = ${r.mr.toFixed(3)} · HC/HK ≈ ${r.hc.toFixed(3)}`;}
if(mode==='mh'){const r=remanenceAndCoercivity(loops),spm=Array.from({length:601},(_,i)=>{const x=-3+i*.01;return{x,y:L(8*x)}});key([[tr('SW : régime bloqué idéal','SW: ideal blocked regime'),blue],[tr('Superparamagnétique à l’équilibre','Superparamagnetic at equilibrium'),green]]);$('graph').innerHTML=graph([{data:loops.down,color:blue},{data:loops.up,color:blue},{data:spm,color:green}],[-3,3],[-1.1,1.1],'H / HK','M / MS',[{x:0,y:r.mr,text:'MR/MS',dx:47,dy:-8},{x:-r.hc,y:0,text:'−HC/HK',dx:-44,dy:-16},{x:2.5,y:1,text:'MS',dy:-10}]);$('readout').textContent=`SW : MR/MS = ${r.mr.toFixed(3)} · HC/HK ≈ ${r.hc.toFixed(3)}. `+tr('Équilibre superparamagnétique : MR = 0 ; HC = 0.','Superparamagnetic equilibrium: MR = 0; HC = 0.');}
if(mode==='initial'){const T=value('temp',300),d=value('diameter',14),sigma=value('width',.12),data=Array.from({length:301},(_,i)=>({x:i*500/300,y:magnetization(i*.5/300,T,d,sigma)}));key([['Langevin',blue]]);$('graph').innerHTML=graph([{data,color:blue}],[0,500],[0,1.05],'μ₀H (mT)','M / MS');$('readout').textContent=`T = ${T} K · d₅₀ = ${d} nm · M(500 mT)/MS = ${data.at(-1).y.toFixed(3)}`;}
if(mode==='zfc'){const selected=$('protocol').value==='f'?thermal.f:thermal.z,p=selected[index];$('timeline').value=index;$('temperature').textContent=`${p.x.toFixed(0)} K`;key([['ZFC',blue],['FC',orange]]);$('graph').innerHTML=graph([{data:thermal.z,color:blue},{data:thermal.f,color:orange}],[0,600],[0,Math.max(...thermal.f.map(p=>p.y),...thermal.z.map(p=>p.y))*1.15],'T (K)','M / MS',[{x:p.x,y:p.y}]);$('particles').innerHTML=particles(p.x);$('readout').textContent=`${$('protocol').value.toUpperCase()}FC · T = ${p.x.toFixed(0)} K · M/MS = ${p.y.toFixed(4)}`.replace('FFC','FC');$('particleHint').textContent=tr('Cuivré : bloqué. Vert : fluctuant. « Maintenir la température » permet d’observer les fluctuations à T fixe.','Copper: blocked. Green: fluctuating. “Hold temperature” lets you observe fluctuations at fixed T.');}}
const drawBefore418=draw;draw=function(){drawBefore418();scientificTypography(document.body)};
window.addEventListener('message',e=>{if(e.source!==parent)return;const v=e.data;if(v?.kind==='protocol'&&['swangle','zfc','mh','initial'].includes(v.mode)){mode=v.mode;lang=v.lang==='en'?'en':'fr';render()}});render();
